public string MinWindow(string s, string t)
{
    if (t.Length == 0 || s.Length < t.Length) return string.Empty;

    // How many of each character t requires
    var need = new Dictionary<char, int>();
    foreach (char c in t)
    {
        need[c] = need.GetValueOrDefault(c) + 1;
    }

    var window = new Dictionary<char, int>();
    int required = need.Count;   // distinct characters that must be satisfied
    int satisfied = 0;

    int left = 0;
    int bestStart = 0;
    int bestLength = int.MaxValue;

    for (int right = 0; right < s.Length; right++)
    {
        char c = s[right];
        window[c] = window.GetValueOrDefault(c) + 1;

        // Did adding c complete this character's requirement?
        if (need.TryGetValue(c, out int needed) && window[c] == needed)
        {
            satisfied++;
        }

        // Shrink while the window is still valid
        while (satisfied == required)
        {
            if (right - left + 1 < bestLength)
            {
                bestLength = right - left + 1;
                bestStart = left;
            }

            char leftChar = s[left];
            window[leftChar]--;

            // Removing leftChar broke a requirement
            if (need.TryGetValue(leftChar, out int needLeft) && window[leftChar] < needLeft)
            {
                satisfied--;
            }

            left++;
        }
    }

    return bestLength == int.MaxValue ? string.Empty : s.Substring(bestStart, bestLength);
}

public string MinWindow(string s, string t)
{
    if (t.Length == 0 || s.Length < t.Length) return string.Empty;

    var need = new Dictionary<char, int>();
    foreach (char c in t) need[c] = need.GetValueOrDefault(c) + 1;

    var window = new Dictionary<char, int>();
    int required = need.Count, satisfied = 0;
    int left = 0, bestStart = 0, bestLength = int.MaxValue;

    for (int right = 0; right < s.Length; right++)
    {
        char c = s[right];
        window[c] = window.GetValueOrDefault(c) + 1;
        if (need.TryGetValue(c, out int n) && window[c] == n) satisfied++;

        while (satisfied == required)
        {
            if (right - left + 1 < bestLength)
            {
                bestLength = right - left + 1;
                bestStart = left;
            }

            char lc = s[left];
            window[lc]--;
            if (need.TryGetValue(lc, out int nl) && window[lc] < nl) satisfied--;
            left++;
        }
    }

    return bestLength == int.MaxValue ? string.Empty : s.Substring(bestStart, bestLength);
}
